/// Every value this sketch keeps: the design and the panel it is drawn on, created once by setup() and used by the loop in
/// main().
pub struct State {
    /// The panel, its touch controller and the card, brought up by `panel::init`.
    hardware: panel::Hardware,

    /// The design -- the markup compiled from src/ui.kdl, and the state a finger moves through it.
    design: ui::Designer,
}

/// One-time initialisation -- the Arduino setup().
///
/// Brings the panel up, paints the design and hands both back as a State for main() to run. Everything
/// that must happen once, and only once, belongs here.
pub async fn setup(spawner: Spawner) -> State {
    info!("=== {} {} starting ===", env!("CARGO_PKG_NAME"), env!("CARGO_PKG_VERSION"));
    // Nothing here is spawned: the panel owns the main loop and there is no radio.
    let _ = spawner;

    let p = embassy_rp::init(Default::default());
    // The whole peripheral set goes in and the panel hands back what it did not take: an exclusive
    // borrow would keep the radio's pins out of reach for the life of the program.
    let (mut hardware, rest) = panel::init(p);

    let _ = rest;

    // The panel keeps whatever the previous frame left in it until something clears it, so the first
    // clear is part of bringing it up.
    hardware
        .display
        .clear(Rgb565::BLACK)
        .expect("the panel accepted the clear");


    // The drawing area is the panel's turned size, not its native one: mipidsi swaps the two itself for
    // a vertical rotation, so the design has to be laid out against what it will actually paint.
    let mut design = ui::Designer::new(
        panel::DRAW_WIDTH as u32,
        panel::DRAW_HEIGHT as u32,
    );
    design
        .repaint(&mut hardware.display)
        .expect("the design did not render");

    // A design with a clock starts from the time the board was built: better than 00:00:00, and what a
    // board with no radio and no PC on the cable will show until the app sets it.
    if ui::HAS_CLOCK {
        let (hour, minute, second) = boot_time();
        design.set_wall_clock(hour, minute, second);
        info!("clock: starting from the build time {:02}:{:02}:{:02}", hour, minute, second);
    }

    info!(
        "designer: {}x{} at rotation {}",
        panel::DRAW_WIDTH,
        panel::DRAW_HEIGHT,
        match panel::ROTATION {
            mipidsi::options::Rotation::Deg90 => 1u8,
            mipidsi::options::Rotation::Deg180 => 2,
            mipidsi::options::Rotation::Deg270 => 3,
            _ => 0,
        }
    );

    State { hardware, design }
}

/// The sketch's entry point -- the Arduino main() around setup() and the loop.
///
/// setup() runs once, then the implementation below repeats for as long as the board is powered. This is
/// the function to edit: everything it needs from setup() is in state.
#[embassy_executor::main(executor = "embassy_rp::executor::Executor", entry = "cortex_m_rt::entry")]
async fn main(spawner: Spawner) {
    let mut state = setup(spawner).await;

    loop {

        // No touch controller on this module: the design is driven by its own timers and events.

        // Events a widget queued (a click, a page change) are dispatched here, once per tick.
        state.design.pump();

        // Only the rectangles that changed are repainted: a full clear of a 320x480 panel is slow enough
        // to be felt as a flicker, which is why the design tracks damage rather than redrawing.
        //
        // `render`, not `repaint`: the two look interchangeable and are not. `render` fills each
        // damaged rectangle with `ui::SCREEN_BACKGROUND` before it redraws the widgets inside it, which is
        // what erases the pixels a moving clock hand has left behind -- a clock draws its hands straight onto
        // the panel and has no opaque face of its own to cover them. `repaint` paints the whole screen
        // *without* that clear, so every tick left the previous hands on the glass (bench, 2026-10-27).
        // `repaint` is right exactly once, in setup(), where the panel has just been cleared.
        if state.design.is_dirty() {
            state
                .design
                .render(&mut state.hardware.display)
                .expect("the design did not render");
        }

        Timer::after(Duration::from_millis(20)).await;
    }
}
